function load(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
function save(key,val){localStorage.setItem(key,JSON.stringify(val))}
let menu=load(STORAGE.menu,seedMenu),orders=load(STORAGE.orders,[]),reservations=load(STORAGE.reservations,[]),customer=load(STORAGE.customer,null),accounts=load(STORAGE.accounts,{}),cart=load(STORAGE.cart,{}),activeCategory='All',rawRole=sessionStorage.getItem(STORAGE.admin),adminRole=rawRole==='yes'?'owner':(rawRole==='owner'||rawRole==='kitchen'?rawRole:''),pendingReceipt=null,lastStaffNotice=null,toastTimer;
