function toWhatsAppPhone(phone){let d=String(phone||'').replace(/\D/g,'');if(d.startsWith('0')&&d.length===11)return '234'+d.slice(1);if(d.length===10)return '234'+d;return d}
function customerWhatsAppLink(phone,text){const p=toWhatsAppPhone(phone);return p?`https://wa.me/${p}?text=${encodeURIComponent(text)}`:''}
if(!customer){customer={name:'Guest',phone:'',credits:20,ledger:[{date:new Date().toISOString(),description:'Welcome to R & E Kitchen',amount:20,balance:20}],id:'guest'};save(STORAGE.customer,customer)}
function phoneKey(phone){return String(phone||'').replace(/\D/g,'')}
function saveCustomer(){save(STORAGE.customer,customer);if(customer.phone){accounts[phoneKey(customer.phone)]=customer;save(STORAGE.accounts,accounts)}}
if(customer.phone){accounts[phoneKey(customer.phone)]=customer;save(STORAGE.accounts,accounts)}
customer.credits=Math.max(20,Number(customer.credits)||20);
if(!Array.isArray(menu)||!menu.length)menu=seedMenu;
else{let upgraded=false;const seedById=Object.fromEntries(seedMenu.map(d=>[d.id,d]));menu=menu.map(d=>{if(!d.image&&seedById[d.id]?.image){upgraded=true;return {...d,image:seedById[d.id].image}}return d});if(upgraded)save(STORAGE.menu,menu)}
function persistAll(){save(STORAGE.menu,menu);save(STORAGE.orders,orders);save(STORAGE.reservations,reservations);saveCustomer();save(STORAGE.cart,cart)}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2900)}
function openPanel(id){closePanels();$('#overlay').classList.add('active');if(['cartDrawer','searchDrawer'].includes(id))$('#'+id).classList.add('open');else $('#'+id).classList.add('active');document.body.style.overflow='hidden'}
function closePanels(){ $$('.drawer.open,.modal.active').forEach(el=>el.classList.remove('open','active'));$('#overlay').classList.remove('active');document.body.style.overflow=''; }
function categoriesRender(){let cats=['All',...new Set(menu.map(x=>x.category))];$('#categories').innerHTML=cats.map(c=>`<button class="category-chip ${c===activeCategory?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}
function renderMenu(){categoriesRender();const q=($('#menuSearch')?.value||'').trim().toLowerCase();const items=menu.filter(d=>d.available!==false&&(activeCategory==='All'||d.category===activeCategory)&&(!q||`${d.name} ${d.category} ${d.desc}`.toLowerCase().includes(q)));$('#menuGrid').innerHTML=items.map((d,idx)=>{const custom=Boolean(DISH_OPTIONS[d.id]);return `<article class="dish-card" style="--stagger:${Math.min(idx,11)*45}ms"><div class="dish-image ${d.image?'has-photo':''}" style="background:linear-gradient(135deg,${dishHue(d.id)},#463319)">${d.image?`<img class="dish-photo" src="${esc(d.image)}" alt="${esc(d.name)}" loading="lazy">`:`<span class="dish-emoji">${esc(d.emoji||'🍽️')}</span>`}<span class="dish-tag">${esc(d.tag||d.category)}</span></div><div class="dish-body"><div class="dish-top"><h3>${esc(d.name)}</h3><span class="dish-price">${money(d.price)}</span></div><p>${esc(d.desc||'Fresh from our kitchen.')}</p><div class="dish-bottom"><span class="dish-rating"><b>★</b> ${esc(d.rating||'4.8')} · Fresh</span><button class="add-button" ${custom?`data-customize="${esc(d.id)}"`:`data-add="${esc(d.id)}"`}>${custom?'Customize +':'+ Add'}</button></div></div></article>`}).join('');$('#emptyMenu').hidden=items.length>0;renderSearch()}
function dishHue(seed){let n=0;for(let c of seed)n=(n*31+c.charCodeAt(0))%360;return `hsl(${n} 28% 55%)`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cartEntries(){return Object.entries(cart).map(([key,val])=>{if(typeof val==='number'){const d=menu.find(x=>x.id===key);return val>0&&d?{key,id:key,qty:val,options:[],extraPrice:0,dish:d}:null}if(val&&typeof val==='object'&&val.qty>0){const d=menu.find(x=>x.id===val.id);return d?{key,id:val.id,qty:Number(val.qty),options:val.options||[],extraPrice:Number(val.extraPrice||0),dish:d}:null}return null}).filter(Boolean)}
function addToCart(id,btn=null,options=[],extraPrice=0){const d=menu.find(x=>x.id===id&&x.available!==false);if(!d)return;const key=options.length?`${id}::${options.join('|')}`:id;const existing=cart[key];if(typeof existing==='number'){cart[key]={id,qty:existing+1,options,extraPrice}}else if(existing&&typeof existing==='object'){existing.qty+=1}else{cart[key]={id,qty:1,options,extraPrice}}save(STORAGE.cart,cart);renderCart();const badge=$('#cartCount');if(badge){badge.classList.remove('bump');void badge.offsetWidth;badge.classList.add('bump')}if(btn){btn.classList.add('added');const prev=btn.textContent;btn.textContent='✓ Added';setTimeout(()=>{btn.classList.remove('added');if(btn.textContent==='✓ Added')btn.textContent=prev},900)}showToast(`${d.name} added to your order.`)}
function cartCount(){return cartEntries().reduce((a,e)=>a+e.qty,0)}
function subtotal(){return cartEntries().reduce((sum,e)=>sum+(e.dish.price+e.extraPrice)*e.qty,0)}
function renderCart(){drawCart()}
function whatsappLink(text){return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`}
function buildCartWhatsAppText(){const lines=cartEntries().map(e=>`• ${e.qty}× ${e.dish.name}${e.options.length?` (${e.options.join(', ')})`:''} — ${money((e.dish.price+e.extraPrice)*e.qty)}`);return `Hello R & E Kitchen! I'd like to place an order:\n\n${lines.join('\n')}\n\nFood subtotal: ${money(subtotal())}\n\nPlease confirm availability and total.`}
// Redraw cart rows and checkout summary using current menu records.
function drawCart(){const entries=cartEntries();$('#cartCount').textContent=entries.reduce((s,e)=>s+e.qty,0);if(!entries.length){$('#cartItems').innerHTML='<div class="cart-empty">Your order is still a blank plate.<br>Pick something lovely from the menu.</div>';$('#cartFooter').innerHTML='';return}$('#cartItems').innerHTML=entries.map(e=>{const unit=e.dish.price+e.extraPrice;return `<div class="cart-line"><div><h4>${esc(e.dish.name)}</h4>${e.options.length?`<div class="cart-options">${esc(e.options.join(' · '))}</div>`:''}<small>${money(unit)} each</small><div class="quantity-control"><button data-qty="${esc(e.key)}" data-delta="-1" aria-label="Remove one">−</button><span>${e.qty}</span><button data-qty="${esc(e.key)}" data-delta="1" aria-label="Add one">+</button></div></div><span class="cart-line-price">${money(unit*e.qty)}</span></div>`}).join('');$('#cartFooter').innerHTML=`<div class="subtotal-line"><span>Subtotal</span><b>${money(subtotal())}</b></div><div class="subtotal-line"><span>Delivery (if selected)</span><span>Shown at checkout</span></div><button class="button button-gold" id="checkoutOpen">Continue to checkout <span>↗</span></button><a class="button button-whatsapp" href="${whatsappLink(buildCartWhatsAppText())}" target="_blank" rel="noreferrer">Order via WhatsApp <span>↗</span></a>`}
function openCustomize(id){const d=menu.find(x=>x.id===id);const cfg=DISH_OPTIONS[id];if(!d||!cfg){addToCart(id);return}$('#customizeContent').innerHTML=`<div class="custom-head">${d.image?`<img class="custom-thumb" src="${esc(d.image)}" alt="${esc(d.name)}">`:''}<div><div class="eyebrow"><i></i> MAKE IT YOURS</div><h2 id="customizeTitle">${esc(d.name)}</h2><p class="custom-desc">${esc(d.desc||'')}</p></div></div><form id="customizeForm" data-dish="${esc(d.id)}" class="custom-form">${cfg.groups.map(g=>`<fieldset class="option-group"><legend>${esc(g.label)}</legend><div class="option-pills">${g.choices.map((c,i)=>`<label class="option-pill"><input type="radio" name="grp_${esc(g.name)}" value="${esc(c.label)}" data-price="${c.price}" ${i===0?'checked':''}><span>${esc(c.label)}${c.price?` <em>+${money(c.price)}</em>`:''}</span></label>`).join('')}</div></fieldset>`).join('')}${cfg.extras?.length?`<fieldset class="option-group"><legend>Optional add-ons</legend><div class="option-pills">${cfg.extras.map(ex=>`<label class="option-pill"><input type="checkbox" name="extra" value="${esc(ex.label)}" data-price="${ex.price}"><span>${esc(ex.label)} <em>+${money(ex.price)}</em></span></label>`).join('')}</div></fieldset>`:''}<button class="button button-gold form-wide" type="submit" id="customSubmitBtn">Add to order · ${money(d.price)} <span>↗</span></button></form>`;openPanel('customizeModal')}
function updateCustomizePrice(){const form=$('#customizeForm');if(!form)return;const d=menu.find(x=>x.id===form.dataset.dish);if(!d)return;const extra=[...form.querySelectorAll('input:checked')].reduce((s,el)=>s+Number(el.dataset.price||0),0);$('#customSubmitBtn').innerHTML=`Add to order · ${money(d.price+extra)} <span>↗</span>`}
function renderSearch(){const q=($('#globalSearch')?.value||'').trim().toLowerCase();let results=menu.filter(d=>d.available!==false&&(!q||`${d.name} ${d.category}`.toLowerCase().includes(q))).slice(0,8);$('#searchResults').innerHTML=results.map(d=>{const custom=Boolean(DISH_OPTIONS[d.id]);return `<div class="search-result"><div class="search-result-info">${d.image?`<img class="search-thumb" src="${esc(d.image)}" alt="" loading="lazy">`:''}<div><b>${esc(d.name)}</b><small>${esc(d.category)} · ${money(d.price)}</small></div></div><button ${custom?`data-customize="${esc(d.id)}"`:`data-add="${esc(d.id)}"`}>${custom?'Customize':'+ Add'}</button></div>`}).join('')||'<div class="cart-empty">No dishes found just yet.</div>'}
function clearPendingReceipt(){pendingReceipt=null;const inp=$('#receiptInput');if(inp)inp.value='';if($('#receiptPreview'))$('#receiptPreview').hidden=true;if($('#receiptDropzone'))$('#receiptDropzone').hidden=false}
function compressReceiptImage(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/i.test(file.type)){reject(new Error('Please upload a JPG or PNG image.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read file.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Invalid image file.'));img.onload=()=>{const maxW=820,scale=Math.min(1,maxW/img.width),w=Math.round(img.width*scale),h=Math.round(img.height*scale);const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve({dataUrl:c.toDataURL('image/jpeg',0.72),fileName:file.name,file})};img.src=reader.result};reader.readAsDataURL(file)})}
function openReservationModal(){const f=$('#reservationForm');if(f){if(customer?.name&&customer.name!=='Guest')f.elements.namedItem('name').value=customer.name;if(customer?.phone)f.elements.namedItem('phone').value=customer.phone}openPanel('reservationModal')}
function openCheckout(){if(!cartCount()){showToast('Add something from the menu to get started.');return}const f=$('#checkoutForm');f.elements.namedItem('name').value=(customer?.name&&customer.name!=='Guest')?customer.name:'';f.elements.namedItem('phone').value=customer?.phone||'';if(f.elements.namedItem('senderName')&&customer?.name&&customer.name!=='Guest')f.elements.namedItem('senderName').value=customer.name;clearPendingReceipt();updateCheckout();closePanels();openPanel('checkoutModal')}
function deliveryFee(){return $('#fulfillment').value==='Delivery'?DELIVERY_FEE:0}
function requestedCredits(){return Math.max(0,Math.floor(Number($('#creditsInput').value)||0))}
function requiresTransfer(){return $('#fulfillment').value==='Delivery'||$('#paymentMethod')?.value==='OPay transfer'}
function updateCheckout(){const input=$('#creditsInput');const max=customer.credits-20;input.max=String(Math.max(0,max));let cr=requestedCredits();if(cr>max){cr=Math.max(0,max);input.value=cr}const isDelivery=$('#fulfillment').value==='Delivery';const fee=deliveryFee(),sub=subtotal(),discount=Math.min(sub,cr*10),total=Math.max(0,sub+fee-discount);$('#creditAvailability').textContent=`${customer.credits} credits available · up to ${Math.max(0,max)} redeemable (₦10 each)`;$('#addressField').hidden=!isDelivery;$('#landmarkField').hidden=!isDelivery;$('#addressInput').disabled=!isDelivery;$('#addressInput').required=isDelivery;$('#landmarkInput').disabled=!isDelivery;const pmSel=$('#paymentMethod'),pmField=$('#paymentMethodField');if(isDelivery){pmSel.value='OPay transfer';pmField.hidden=true}else{pmField.hidden=false}const showPay=requiresTransfer();$('#paymentBox').hidden=!showPay;$('#paymentNotice').textContent=isDelivery?'OPAY TRANSFER REQUIRED FOR DELIVERY':'OPAY TRANSFER DETAILS';$('#paymentAmount').textContent=money(total);$('#placeOrderBtn').innerHTML=showPay?`Submit order &amp; payment proof <span>↗</span>`:`Place order <span>↗</span>`;$('#checkoutSummary').innerHTML=`<div class="summary-row"><span>Food subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Delivery fee</span><b>${isDelivery?money(fee):'Free'}</b></div><div class="summary-row"><span>Credits applied (${cr})</span><b>−${money(discount)}</b></div><div class="summary-row total"><span>Total to pay</span><b>${money(total)}</b></div>`}
function setCreditLedger(desc,amount){customer.credits=Math.max(20,Number(customer.credits||20)+amount);customer.ledger=customer.ledger||[];customer.ledger.unshift({date:new Date().toISOString(),description:desc,amount,balance:customer.credits});saveCustomer()}
function showAccount(){if(!customer.name||customer.name==='Guest'){accountLogin();openPanel('accountModal');return}renderAccount();openPanel('accountModal')}
function accountLogin(){const target=$('#accountContent');target.innerHTML=`<div class="eyebrow"><i></i> YOUR KITCHEN ACCOUNT</div><h2 id="accountTitle">Welcome to <em>your table.</em></h2><p style="font-size:10px;color:#817a6e">Enter your name and phone to see your orders, reservations, and kitchen credits. This demo stores information on this device.</p><form id="accountForm" class="form-grid account-form"><label class="form-wide">Your name<input name="name" required placeholder="Full name"></label><label class="form-wide">Phone number<input name="phone" required type="tel" placeholder="080..." pattern="[+0-9 ()-]{7,}"></label><button class="button button-gold form-wide" type="submit">Continue <span>↗</span></button></form>`}
function renderAccount(){const c=customer,ownOrders=orders.filter(o=>o.phone===c.phone).slice().reverse(),ownRes=reservations.filter(r=>r.phone===c.phone).slice().reverse();$('#accountContent').innerHTML=`<div class="dashboard-head"><div><div class="eyebrow"><i></i> YOUR KITCHEN ACCOUNT</div><h2 id="accountTitle">Good to see you, ${esc(c.name.split(' ')[0])}.</h2><p>Your orders, reservations and kitchen credits, together in one place.</p></div><div class="admin-top-actions"><button id="accountEdit">Edit profile</button><button id="accountSignout">Sign out</button></div></div><div class="wallet-panel"><div><small>YOUR KITCHEN CREDITS</small><b>${c.credits} credits</b><span>₦10 per credit · 20-credit minimum balance</span></div><span>Earn 1 credit per ₦1,000 paid<br>Redeem only credits above 20</span></div><div class="account-action-row"><button class="button button-gold" id="accountOrder">Start an order ↗</button><button class="button button-dark" id="accountReserve">Reserve a table ↗</button></div><h3 class="account-section-title">Your recent orders</h3>${ownOrders.length?`<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>ORDER</th><th>DATE</th><th>ITEMS</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody>${ownOrders.slice(0,8).map(o=>`<tr><td>${esc(o.id)}</td><td>${dateShort(o.date)}</td><td>${o.items.reduce((n,i)=>n+i.qty,0)} items · ${esc(o.fulfillment)}</td><td>${money(o.total)}</td><td><span class="status-pill ${statusClass(o.status)}">${esc(o.status)}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="admin-help">No orders yet. Your first plate is just a menu away.</p>'}<h3 class="account-section-title">Your table reservations</h3>${ownRes.length?`<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>DATE</th><th>TIME</th><th>GUESTS</th><th>STATUS</th></tr></thead><tbody>${ownRes.map(r=>`<tr><td>${dateShort(r.date)}</td><td>${esc(r.time)}</td><td>${esc(r.guests)}</td><td><span class="status-pill ${statusClass(r.status)}">${esc(r.status)}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="admin-help">No reservations just yet.</p>'}<h3 class="account-section-title">Credit activity</h3><div class="credit-history">${(c.ledger||[]).slice(0,6).map(x=>`<div><span>${esc(x.description)} <small>· ${dateShort(x.date)}</small></span><b>${x.amount>0?'+':''}${x.amount} → ${x.balance}</b></div>`).join('')||'<div>No credit activity yet.</div>'}</div>`}
function dateShort(date){return new Date(date).toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'})}
function statusClass(s){return String(s||'').toLowerCase().replace(/[^a-z]/g,'')}
function showAdmin(){if(!adminRole){renderAdminLogin()}else renderAdminDashboard('Overview');openPanel('adminModal')}
function renderAdminLogin(){ $('#adminContent').innerHTML=`<div class="admin-login"><div class="eyebrow"><i></i> R & E KITCHEN · STAFF PORTAL</div><h2 id="adminTitle">Good evening,<br><em>team.</em></h2><p>Sign in with your Kitchen Staff or Owner PIN to manage orders, payments, reservations, and menu.</p><form id="adminLoginForm" class="form-grid"><label class="form-wide">Access PIN<input name="pin" type="password" required inputmode="numeric" placeholder="Enter PIN"></label><button class="button button-gold form-wide" type="submit">Sign in <span>↗</span></button></form><p class="admin-help">Demo PINs · <b>Kitchen Staff:</b> 1234 (orders, payments &amp; reservations) · <b>Admin / Owner:</b> 2026 (full access + menu pricing &amp; dishes).</p></div>`}
function renderAdminDashboard(tab='Overview'){let categories=['Overview','Orders','Reservations','Menu'];const roleLabel=isOwner()?'Admin / Owner':'Kitchen Staff';const pendingPay=orders.filter(o=>o.paymentStatus==='Awaiting Verification').length;$('#adminContent').innerHTML=`<div class="dashboard-head"><div><div class="eyebrow"><i></i> R & E KITCHEN · <span class="role-badge ${isOwner()?'owner':'kitchen'}">${roleLabel}</span></div><h2 id="adminTitle">Kitchen dashboard</h2><p>${isOwner()?'Full access · Orders, payments, reservations &amp; menu pricing':'Kitchen staff · Manage orders, verify payments &amp; reservations'}</p></div><div class="admin-top-actions"><a href="#home" id="adminVisitSite">View website ↗</a><button id="adminLogout">Sign out</button></div></div>${lastStaffNotice?`<div class="staff-wa-banner"><span>${esc(lastStaffNotice.text)}</span><a class="small-btn wa-btn" href="${esc(lastStaffNotice.url)}" target="_blank" rel="noreferrer">Notify customer on WhatsApp ↗</a></div>`:''}<nav class="dashboard-tabs">${categories.map(t=>`<button class="dash-tab ${t===tab?'active':''}" data-admin-tab="${t}">${t}${t==='Orders'&&pendingPay?` <span class="tab-badge">${pendingPay}</span>`:''}</button>`).join('')}</nav><div id="adminTabContent">${adminTabMarkup(tab)}</div>`}
function adminTabMarkup(tab){if(tab==='Overview'){const today=new Date().toDateString(),todayOrders=orders.filter(o=>new Date(o.date).toDateString()===today),awaitingPay=orders.filter(o=>o.paymentStatus==='Awaiting Verification').length;return `<div class="stats-grid"><div class="stat-card"><small>ORDERS TODAY</small><b>${todayOrders.length}</b></div><div class="stat-card"><small>AWAITING PAYMENT CHECK</small><b>${awaitingPay}</b></div><div class="stat-card"><small>OPEN ORDERS</small><b>${orders.filter(o=>!['Completed','Cancelled'].includes(o.status)).length}</b></div><div class="stat-card"><small>RESERVATIONS</small><b>${reservations.filter(r=>!['Completed','Cancelled'].includes(r.status)).length}</b></div></div><h3 class="account-section-title">Latest orders</h3>${adminOrdersTable(orders.slice().reverse().slice(0,6))}<h3 class="account-section-title">Upcoming reservations</h3>${adminReservationsTable(reservations.filter(r=>r.status!=='Cancelled').slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5))}`}
if(tab==='Orders')return `<h3 class="account-section-title">All orders <span class="admin-help">(${orders.length})</span></h3>${adminOrdersTable(orders.slice().reverse())}`;
if(tab==='Reservations')return `<h3 class="account-section-title">Reservations <span class="admin-help">(${reservations.length})</span></h3>${adminReservationsTable(reservations.slice().sort((a,b)=>a.date.localeCompare(b.date)))}`;
return `<div class="menu-admin"><h3>Menu items (${menu.length})</h3>${isOwner()?`<button class="small-btn primary" id="addMenuOpen">+ Add menu item</button>`:`<span class="owner-lock-note">Owner PIN required to edit prices or add dishes</span>`}</div><div id="menuEditor"></div>${adminMenuTable()}`}
function staffCustomerMessage(o,kind){
  const first=(o.name||'there').split(' ')[0];
  if(kind==='approved')return `Hello ${first}! Your payment of ${money(o.total)} for R & E Kitchen order *${o.id}* has been verified. Our kitchen has started preparing your meal now!`;
  if(kind==='rejected')return `Hello ${first}, we couldn't verify the payment screenshot for R & E Kitchen order *${o.id}* (${money(o.total)}). Please reply with a clear OPay transfer receipt so we can start your order.`;
  if(kind==='ready'){
    if(o.fulfillment==='Delivery')return `Hello ${first}! Your R & E Kitchen order *${o.id}* is freshly prepared and ready for dispatch to ${o.address||'your address'}. Our rider will call shortly!`;
    if(o.fulfillment==='Pickup')return `Hello ${first}! Your R & E Kitchen order *${o.id}* is hot and ready for pickup at our kitchen (Off Abacha Road, Karu). See you soon!`;
    return `Hello ${first}! Your R & E Kitchen order *${o.id}* is ready!`;
  }
  return `Hello ${first}, update on your R & E Kitchen order *${o.id}*: Status is now *${o.status}*.`;
}
function adminOrdersTable(list){if(!list.length)return '<p class="admin-help">No orders yet.</p>';return `<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>ITEMS</th><th>PAYMENT</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${list.map(o=>{const payStatus=o.paymentStatus||(o.fulfillment==='Delivery'?'Awaiting Verification':'Pay on Arrival');const waKind=o.status==='Ready'?'ready':(payStatus==='Verified'&&o.status==='Preparing'?'approved':(payStatus==='Rejected'?'rejected':'update'));const waUrl=customerWhatsAppLink(o.phone,staffCustomerMessage(o,waKind));return `<tr><td>${esc(o.id)}<br><small>${dateShort(o.date)}</small></td><td>${esc(o.name)}<br><small>${esc(o.phone)}</small></td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}${i.options?.length?` (${esc(i.options.join(', '))})`:''}`).join(', ')}<br><small>${esc(o.fulfillment)}${o.address?' · '+esc(o.address):''}${o.landmark?' ('+esc(o.landmark)+')':''}</small></td><td><b>${money(o.total)}</b><br><span class="status-pill ${statusClass(payStatus)}">${esc(payStatus)}</span>${o.receipt?`<br><button type="button" class="link-mini" data-view-receipt="${esc(o.id)}">View receipt</button>`:''}</td><td><span class="status-pill ${statusClass(o.status)}">${esc(o.status)}</span></td><td><div class="admin-actions-col">${payStatus==='Awaiting Verification'?`<button type="button" class="small-btn primary" data-approve-order="${esc(o.id)}">✓ Verify &amp; Prep</button>`:''}<div class="admin-actions"><select class="small-btn order-status" data-order-status="${esc(o.id)}" title="Order status"><option ${o.status==='Awaiting Payment'?'selected':''}>Awaiting Payment</option><option ${o.status==='Pending'?'selected':''}>Pending</option><option ${o.status==='Preparing'?'selected':''}>Preparing</option><option ${o.status==='Ready'?'selected':''}>Ready</option><option ${o.status==='Completed'?'selected':''}>Completed</option><option ${o.status==='Cancelled'?'selected':''}>Cancelled</option></select><select class="small-btn payment-status" data-payment-status="${esc(o.id)}" title="Payment status"><option ${payStatus==='Awaiting Verification'?'selected':''}>Awaiting Verification</option><option ${payStatus==='Verified'?'selected':''}>Verified</option><option ${payStatus==='Rejected'?'selected':''}>Rejected</option><option ${payStatus==='Pay on Arrival'?'selected':''}>Pay on Arrival</option></select></div>${waUrl?`<a class="small-btn wa-btn" href="${esc(waUrl)}" target="_blank" rel="noreferrer">WhatsApp customer ↗</a>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`}
function adminReservationsTable(list){if(!list.length)return '<p class="admin-help">No reservations to show.</p>';return `<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>GUEST</th><th>DATE & TIME</th><th>PARTY</th><th>CONTACT</th><th>NOTE</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.name)}</td><td>${dateShort(r.date)}<br><small>${esc(r.time)}</small></td><td>${esc(r.guests)}</td><td>${esc(r.phone)}</td><td>${esc(r.note||'—')}</td><td><span class="status-pill ${statusClass(r.status)}">${esc(r.status)}</span></td><td><select class="small-btn reservation-status" data-reservation-status="${esc(r.id)}"><option ${r.status==='Requested'?'selected':''}>Requested</option><option ${r.status==='Confirmed'?'selected':''}>Confirmed</option><option ${r.status==='Completed'?'selected':''}>Completed</option><option ${r.status==='Cancelled'?'selected':''}>Cancelled</option></select></td></tr>`).join('')}</tbody></table></div>`}
function adminMenuTable(){return `<div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>ITEM</th><th>CATEGORY</th><th>PRICE</th><th>AVAILABILITY</th>${isOwner()?'<th>ACTIONS</th>':''}</tr></thead><tbody>${menu.map(d=>`<tr><td>${esc(d.emoji)} ${esc(d.name)}<br><small>${esc(d.desc||'')}</small></td><td>${esc(d.category)}</td><td>${money(d.price)}</td><td>${d.available===false?'Paused':'Available'}</td>${isOwner()?`<td><div class="admin-actions"><button class="small-btn" data-edit-dish="${esc(d.id)}">Edit</button><button class="small-btn" data-toggle-dish="${esc(d.id)}">${d.available===false?'Enable':'Pause'}</button><button class="small-btn" data-delete-dish="${esc(d.id)}">Delete</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function menuForm(d=null){if(!isOwner()){showToast('Only Admin / Owner can edit prices or add dishes.');return}const editor=$('#menuEditor');editor.innerHTML=`<form id="menuItemForm" class="admin-inline-form"><input name="name" required placeholder="Dish name" value="${esc(d?.name||'')}"><select name="category">${['Rice & bowls','Soups & swallows','Small chops','From the grill','Drinks','Desserts'].map(c=>`<option ${d?.category===c?'selected':''}>${c}</option>`).join('')}</select><input name="price" type="number" min="0" required placeholder="Price in ₦" value="${d?.price||''}"><input name="desc" placeholder="Short description" value="${esc(d?.desc||'')}"><button class="small-btn primary" type="submit">${d?'Save':'Add item'}</button>${d?`<button class="small-btn" type="button" id="cancelDishEdit">Cancel</button>`:''}<input name="id" type="hidden" value="${esc(d?.id||'')}"></form>`;editor.scrollIntoView({block:'nearest',behavior:'smooth'})}
function openReceiptLightbox(orderId){const o=orders.find(x=>x.id===orderId);if(!o||!o.receipt)return;$('#receiptLightboxBody').innerHTML=`<h3>Payment Receipt · ${esc(o.id)}</h3><p class="admin-help">${esc(o.name)} · ${money(o.total)}${o.senderName?` · Sender: ${esc(o.senderName)}`:''}</p><img class="lightbox-img" src="${esc(o.receipt)}" alt="OPay transfer receipt">${o.paymentStatus==='Awaiting Verification'?`<div class="lightbox-actions"><button type="button" class="button button-gold" data-lb-approve="${esc(o.id)}">Verify payment &amp; start prep ✓</button><button type="button" class="button button-dark" data-lb-reject="${esc(o.id)}">Reject payment</button></div>`:''}`;$('#receiptLightbox').hidden=false}
function closeReceiptLightbox(){$('#receiptLightbox').hidden=true}
// Confirmations, Calendar Export, Order Tracking & Live Status
function orderWhatsAppText(order){
  const lines=order.items.map(i=>`• ${i.qty}× ${i.name}${i.options?.length?` (${i.options.join(', ')})`:''} — ${money(i.price*i.qty)}`);
  const payLine=order.paymentMethod==='OPay transfer'?`\nPayment: OPay transfer to ${OPAY_ACCOUNT.number}${order.senderName?` (Sender: ${order.senderName})`:''}\nReceipt: Uploaded on site (attaching screenshot here)`:`\nPayment: Pay on arrival`;
  return `Hello R & E Kitchen! I just placed order *${order.id}*:\n\n${lines.join('\n')}\n\nFulfillment: ${order.fulfillment}${order.address?`\nAddress: ${order.address}`:''}${order.landmark?`\nLandmark: ${order.landmark}`:''}\nName: ${order.name}\nPhone: ${order.phone}${order.delivery?`\nDelivery fee: ${money(order.delivery)}`:''}\nTotal: ${money(order.total)}${payLine}`;
}
function showOrderConfirmation(order,earned){
  const isTransfer=order.paymentMethod==='OPay transfer';
  const eta=isTransfer?'Send your receipt on WhatsApp below — once our kitchen verifies your OPay transfer, preparation starts right away!':(order.fulfillment==='Pickup'?'Ready for pickup in 20–30 mins':'We’ll have your table & meal ready when you arrive');
  $('#confirmContent').innerHTML=`<div class="confirm-badge">✓</div><div class="eyebrow"><i></i> ${isTransfer?'PAYMENT PROOF SUBMITTED':'ORDER CONFIRMED'}</div><h2 id="confirmTitle">Thank you, <em>${esc(order.name.split(' ')[0])}.</em></h2><p class="confirm-sub">Order <b>${esc(order.id)}</b> · ${esc(eta)}</p>${order.receipt?`<div class="confirm-receipt-thumb"><img src="${esc(order.receipt)}" alt="Uploaded payment receipt"><div><b>OPay receipt uploaded</b><small>${esc(order.senderName||'Tap WhatsApp below and attach this screenshot for fastest verification')}</small></div></div>`:''}<div class="confirm-receipt">${order.items.map(i=>`<div class="summary-row"><span>${i.qty}× ${esc(i.name)}${i.options?.length?` <small>(${esc(i.options.join(', '))})</small>`:''}</span><b>${money(i.price*i.qty)}</b></div>`).join('')}${order.delivery?`<div class="summary-row"><span>Delivery fee</span><b>${money(order.delivery)}</b></div>`:''}${order.discount?`<div class="summary-row"><span>Credits applied</span><b>−${money(order.discount)}</b></div>`:''}<div class="summary-row total"><span>Total</span><b>${money(order.total)}</b></div>${earned?`<div class="confirm-reward">✦ You earned +${earned} kitchen credit${earned>1?'s':''} on this order!</div>`:''}</div><div class="confirm-actions"><a class="button button-whatsapp" href="${whatsappLink(orderWhatsAppText(order))}" target="_blank" rel="noreferrer">Send order &amp; receipt on WhatsApp <span>↗</span></a><button class="button button-dark" type="button" data-track-order="${esc(order.id)}">Track order status <span>→</span></button></div>`;
  openPanel('confirmModal');
}
function downloadReservationICS(r){
  const dt=r.date.replace(/-/g,'');
  const m=r.time.match(/(\d+):(\d+)\s*(am|pm)/i);
  let hr=m?Number(m[1]):12;const min=m?Number(m[2]):0;const ampm=m?m[3].toLowerCase():'pm';
  if(ampm==='pm'&&hr<12)hr+=12;if(ampm==='am'&&hr===12)hr=0;
  const pad=n=>String(n).padStart(2,'0');
  const start=`${dt}T${pad(hr)}${pad(min)}00`,end=`${dt}T${pad(Math.min(23,hr+2))}${pad(min)}00`;
  const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//R and E Kitchen//Reservation//EN','BEGIN:VEVENT',`UID:${r.id}@rekitchen`,`DTSTART:${start}`,`DTEND:${end}`,'SUMMARY:Table Reservation at R & E Kitchen',`DESCRIPTION:Reservation ${r.id} for ${r.guests}. ${r.note||''}`,'LOCATION:Off Abacha Road, Hangwa Hashimu, Karu, Nasarawa State','END:VEVENT','END:VCALENDAR'].join('\r\n');
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([ics],{type:'text/calendar'}));a.download=`RE-Kitchen-${r.id}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);
}
function showReservationConfirmation(r){
  const waText=`Hello R & E Kitchen! I just requested table reservation *${r.id}*:\n• Name: ${r.name}\n• Date: ${dateShort(r.date)} at ${r.time}\n• Party: ${r.guests}${r.note?`\n• Note: ${r.note}`:''}`;
  $('#confirmContent').innerHTML=`<div class="confirm-badge">✓</div><div class="eyebrow"><i></i> SEAT RESERVED</div><h2 id="confirmTitle">See you soon, <em>${esc(r.name.split(' ')[0])}.</em></h2><p class="confirm-sub">Reference <b>${esc(r.id)}</b> · We’ll confirm by phone or when you arrive.</p><div class="confirm-receipt"><div class="summary-row"><span>Date</span><b>${dateShort(r.date)}</b></div><div class="summary-row"><span>Time</span><b>${esc(r.time)}</b></div><div class="summary-row"><span>Party size</span><b>${esc(r.guests)}</b></div>${r.note?`<div class="summary-row"><span>Note</span><b>${esc(r.note)}</b></div>`:''}</div><div class="confirm-actions"><a class="button button-whatsapp" href="${whatsappLink(waText)}" target="_blank" rel="noreferrer">Confirm on WhatsApp <span>↗</span></a><button class="button button-dark" type="button" id="downloadIcsBtn">Add to Calendar (.ics) <span>↓</span></button></div>`;
  openPanel('confirmModal');
  $('#downloadIcsBtn')?.addEventListener('click',()=>downloadReservationICS(r));
}
function renderTrackResult(query){
  const target=$('#trackResult');
  const q=String(query||'').trim().toUpperCase();
  if(!q){
    const recent=orders.slice().reverse().slice(0,4);
    target.innerHTML=recent.length?`<div class="track-recent"><small>YOUR RECENT ORDERS</small>${recent.map(o=>`<button type="button" class="track-chip" data-track-order="${esc(o.id)}"><b>${esc(o.id)}</b><span>${esc(o.status)} · ${money(o.total)}</span></button>`).join('')}</div>`:'<p class="admin-help" style="margin-top:14px">Enter the Order ID from your confirmation screen (e.g. RE-1234567).</p>';
    return;
  }
  const order=orders.find(o=>o.id.toUpperCase()===q);
  if(!order){target.innerHTML=`<p class="admin-help" style="margin-top:16px">No order found matching <b>${esc(q)}</b> in this browser. Check the ID and try again.</p>`;return}
  const steps=order.paymentMethod==='OPay transfer'?['Awaiting Payment','Preparing','Ready','Completed']:['Pending','Preparing','Ready','Completed'];
  const stepLabels=order.paymentMethod==='OPay transfer'?['Payment check','Preparing','Ready','Completed']:steps;
  const idx=Math.max(0,steps.indexOf(order.status));
  const cancelled=order.status==='Cancelled';
  target.innerHTML=`<div class="track-card"><div class="track-head"><div><b>${esc(order.id)}</b><small>${dateShort(order.date)} · ${esc(order.fulfillment)}${order.paymentStatus?` · Payment: ${esc(order.paymentStatus)}`:''}</small></div><span class="status-pill ${statusClass(order.status)}">${esc(order.status)}</span></div>${cancelled?'<p class="admin-help" style="margin:12px 0">This order was cancelled.</p>':`<div class="track-steps">${stepLabels.map((s,i)=>`<div class="track-step ${i<=idx?'done':''} ${i===idx?'current':''}"><i></i><span>${s}</span></div>`).join('')}</div>`}<div class="confirm-receipt" style="margin-top:14px">${order.items.map(i=>`<div class="summary-row"><span>${i.qty}× ${esc(i.name)}${i.options?.length?` <small>(${esc(i.options.join(', '))})</small>`:''}</span><b>${money(i.price*i.qty)}</b></div>`).join('')}${order.delivery?`<div class="summary-row"><span>Delivery fee</span><b>${money(order.delivery)}</b></div>`:''}<div class="summary-row total"><span>Total</span><b>${money(order.total)}</b></div></div></div>`;
}
function openTrackModal(prefillId=''){
  openPanel('trackModal');
  const input=$('#trackForm')?.elements.namedItem('orderId');
  if(input)input.value=prefillId;
  renderTrackResult(prefillId);
}
function updateKitchenStatus(){
  const el=$('#kitchenStatus');
  if(!el)return;
  const hr=new Date().getHours();
  const isOpen=hr>=10&&hr<21;
  el.classList.toggle('is-open',isOpen);
  el.classList.toggle('is-closed',!isOpen);
  el.innerHTML=`<i></i> ${isOpen?'OPEN NOW · CLOSES AT 9:00 PM':'KITCHEN CLOSED · OPENS AT 10:00 AM'}`;
}
// Events
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;activeCategory=b.dataset.category;renderMenu()});$('#menuSearch').addEventListener('input',renderMenu);$('#menuGrid').addEventListener('click',e=>{const c=e.target.closest('[data-customize]');if(c){openCustomize(c.dataset.customize);return}const b=e.target.closest('[data-add]');if(b)addToCart(b.dataset.add,b)});
$('#clearMenuFilters')?.addEventListener('click',()=>{activeCategory='All';$('#menuSearch').value='';renderMenu()});
$('#customizeContent').addEventListener('change',updateCustomizePrice);
