$$('a[href="#track"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openTrackModal()}));
$('#cartOpen').addEventListener('click',()=>{drawCart();openPanel('cartDrawer')});$('#cartDrawer').addEventListener('click',e=>{const q=e.target.closest('[data-qty]');if(q){const key=q.dataset.qty,delta=Number(q.dataset.delta),cur=cart[key];if(typeof cur==='number'){const next=cur+delta;if(next<=0)delete cart[key];else cart[key]=next}else if(cur&&typeof cur==='object'){cur.qty+=delta;if(cur.qty<=0)delete cart[key]}save(STORAGE.cart,cart);drawCart();return}if(e.target.id==='checkoutOpen')openCheckout()});$('#searchOpen').addEventListener('click',()=>{renderSearch();openPanel('searchDrawer');setTimeout(()=>$('#globalSearch').focus(),100)});$('#globalSearch').addEventListener('input',renderSearch);$('#searchResults').addEventListener('click',e=>{const c=e.target.closest('[data-customize]');if(c){openCustomize(c.dataset.customize);return}const b=e.target.closest('[data-add]');if(b){addToCart(b.dataset.add,b);drawCart()}});
$('#overlay').addEventListener('click',closePanels);$$('[data-close]').forEach(b=>b.addEventListener('click',closePanels));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#receiptLightbox')?.hidden){closeReceiptLightbox();return}closePanels()}});
$('#reserveOpen').addEventListener('click',openReservationModal);$$('a[href="#reserve"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openReservationModal()}));$('#reservationForm').date.min=new Date().toISOString().slice(0,10);$('#reservationForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(new Date(data.date+'T00:00:00')<new Date(new Date().toDateString())){showToast('Please choose today or a future date.');return}const r={...data,id:'RES-'+Date.now().toString().slice(-6),status:'Requested',created:new Date().toISOString()};reservations.push(r);if(data.phone===customer.phone){customer.name=data.name;saveCustomer()}save(STORAGE.reservations,reservations);e.target.reset();showReservationConfirmation(r)});
$('#fulfillment').addEventListener('change',updateCheckout);$('#paymentMethod')?.addEventListener('change',updateCheckout);$('#creditsInput').addEventListener('input',updateCheckout);
$('#copyAccountBtn')?.addEventListener('click',()=>{navigator.clipboard?.writeText(OPAY_ACCOUNT.number).then(()=>showToast('OPay account number copied: '+OPAY_ACCOUNT.number)).catch(()=>showToast('OPay account: '+OPAY_ACCOUNT.number))});
$('#receiptInput')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{pendingReceipt=await compressReceiptImage(file);$('#receiptPreviewImg').src=pendingReceipt.dataUrl;$('#receiptFileName').textContent=pendingReceipt.fileName;$('#receiptPreview').hidden=false;$('#receiptDropzone').hidden=true;showToast('Payment screenshot attached.')}catch(err){clearPendingReceipt();showToast(err.message||'Please select a JPG or PNG image.')}});
$('#removeReceiptBtn')?.addEventListener('click',()=>{$('#receiptInput').click()});
$('#checkoutForm').elements.namedItem('phone').addEventListener('change',e=>{const p=e.target.value.trim(),key=phoneKey(p);if(!p)return;if(accounts[key]){customer=accounts[key];const nameEl=$('#checkoutForm').elements.namedItem('name');if(nameEl&&!nameEl.value.trim()&&customer.name&&customer.name!=='Guest')nameEl.value=customer.name}else if(key!==phoneKey(customer.phone))customer={id:'cust-'+Date.now(),name:$('#checkoutForm').elements.namedItem('name').value.trim()||'Guest',phone:p,credits:20,ledger:[{date:new Date().toISOString(),description:'Welcome to R & E Kitchen',amount:20,balance:20}]};updateCheckout()});
$('#checkoutForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));const key=phoneKey(data.phone);if(accounts[key])customer=accounts[key];else if(key!==phoneKey(customer.phone))customer={id:'cust-'+Date.now(),name:data.name.trim(),phone:data.phone.trim(),credits:20,ledger:[{date:new Date().toISOString(),description:'Welcome to R & E Kitchen',amount:20,balance:20}]};customer.credits=Math.max(20,Number(customer.credits)||20);updateCheckout();const max=customer.credits-20,cr=requestedCredits();if(data.fulfillment==='Delivery'&&!String(data.address||'').trim()){showToast('Add your delivery address to continue.');return}const needTransfer=requiresTransfer();if(needTransfer&&!pendingReceipt){showToast('Please upload your OPay transfer screenshot (JPG or PNG) before submitting.');return}if(cr>max||cr<0){showToast('Your credit balance must stay at or above 20.');return}if(cr*10>subtotal()){showToast('Credits cannot exceed the food subtotal.');return}const items=cartEntries().map(e=>({id:e.id,name:e.dish.name,price:e.dish.price+e.extraPrice,qty:e.qty,options:e.options}));if(!items.length){showToast('Your cart is empty.');closePanels();return}const before=subtotal()+deliveryFee(),discount=cr*10,total=Math.max(0,before-discount),order={id:'RE-'+Date.now().toString().slice(-7),date:new Date().toISOString(),name:data.name.trim(),phone:data.phone.trim(),fulfillment:data.fulfillment,address:data.fulfillment==='Delivery'?(data.address||'').trim():'',landmark:data.fulfillment==='Delivery'?(data.landmark||'').trim():'',paymentMethod:needTransfer?'OPay transfer':'Pay on arrival',paymentStatus:needTransfer?'Awaiting Verification':'Pay on Arrival',senderName:needTransfer?(data.senderName||data.name).trim():'',receipt:needTransfer?pendingReceipt.dataUrl:'',items,subtotal:subtotal(),delivery:deliveryFee(),creditsUsed:cr,discount,total,status:needTransfer?'Awaiting Payment':'Pending'};orders.push(order);customer.name=data.name.trim();customer.phone=data.phone.trim();if(cr)setCreditLedger(`Credits redeemed on ${order.id}`,-cr);const earned=Math.floor(total/1000);if(earned)setCreditLedger(`Order reward · ${order.id}`,earned);cart={};try{persistAll()}catch{order.receipt='';persistAll();showToast('Order saved (receipt image too large for browser cache — please send on WhatsApp).')}drawCart();f.reset();$('#creditsInput').value='0';clearPendingReceipt();showOrderConfirmation(order,earned)});
$('#receiptLightboxClose')?.addEventListener('click',closeReceiptLightbox);
$('#receiptLightbox')?.addEventListener('click',e=>{if(e.target.id==='receiptLightbox'){closeReceiptLightbox();return}const ap=e.target.closest('[data-lb-approve]');if(ap){const o=orders.find(x=>x.id===ap.dataset.lbApprove);if(o){o.paymentStatus='Verified';o.status='Preparing';save(STORAGE.orders,orders);lastStaffNotice={text:`Payment verified for ${o.id} — prep started!`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'approved'))};closeReceiptLightbox();renderAdminDashboard('Orders');showToast(`Order ${o.id} approved for preparation.`)}return}const rj=e.target.closest('[data-lb-reject]');if(rj){const o=orders.find(x=>x.id===rj.dataset.lbReject);if(o){o.paymentStatus='Rejected';o.status='Awaiting Payment';save(STORAGE.orders,orders);lastStaffNotice={text:`Payment rejected for ${o.id}.`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'rejected'))};closeReceiptLightbox();renderAdminDashboard('Orders');showToast(`Payment marked rejected for ${o.id}.`)}}});
$('#mainNav').addEventListener('click',e=>{if(e.target.closest('a'))$('#mainNav').classList.remove('open')});$('#menuToggle').addEventListener('click',()=>$('#mainNav').classList.toggle('open'));
$$('a[href="#account"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showAccount()}));$('#accountContent').addEventListener('submit',e=>{if(e.target.id!=='accountForm')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const previous=accounts[phoneKey(data.phone)];if(previous){customer={...previous,name:data.name.trim()}}else{customer={id:'cust-'+Date.now(),name:data.name.trim(),phone:data.phone.trim(),credits:20,ledger:[{date:new Date().toISOString(),description:'Welcome to R & E Kitchen',amount:20,balance:20}]}}saveCustomer();renderAccount()});$('#accountContent').addEventListener('click',e=>{if(e.target.closest('#accountOrder')){closePanels();location.hash='#menu'}if(e.target.closest('#accountReserve')){openReservationModal()}if(e.target.closest('#accountEdit')){const c=customer;$('#accountContent').innerHTML=`<div class="eyebrow"><i></i> YOUR KITCHEN ACCOUNT</div><h2 id="accountTitle">Edit <em>your details.</em></h2><form id="accountEditForm" class="form-grid account-form"><label class="form-wide">Your name<input name="name" required value="${esc(c.name)}"></label><label class="form-wide">Phone number<input name="phone" required type="tel" pattern="[+0-9 ()-]{7,}" value="${esc(c.phone)}"></label><button class="button button-gold form-wide">Save changes</button></form>`}if(e.target.closest('#accountSignout')){customer={name:'Guest',phone:'',credits:20,ledger:[{date:new Date().toISOString(),description:'Welcome to R & E Kitchen',amount:20,balance:20}],id:'guest'};save(STORAGE.customer,customer);accountLogin()}});$('#accountContent').addEventListener('submit',e=>{if(e.target.id==='accountEditForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));customer.name=d.name.trim();customer.phone=d.phone.trim();saveCustomer();renderAccount();showToast('Profile updated.')}});
$('#adminShortcut').addEventListener('click',showAdmin);$$('a[href="#admin"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showAdmin()}));$('#adminContent').addEventListener('submit',e=>{if(e.target.id==='adminLoginForm'){e.preventDefault();const pin=e.target.pin.value.trim();if(pin===STAFF_PINS.owner){adminRole='owner';sessionStorage.setItem(STORAGE.admin,'owner');lastStaffNotice=null;renderAdminDashboard();showToast('Signed in as Admin / Owner.')}else if(pin===STAFF_PINS.kitchen){adminRole='kitchen';sessionStorage.setItem(STORAGE.admin,'kitchen');lastStaffNotice=null;renderAdminDashboard('Orders');showToast('Signed in as Kitchen Staff.')}else showToast('That PIN did not match. Try again.')}if(e.target.id==='menuItemForm'){e.preventDefault();if(!isOwner()){showToast('Only Admin / Owner can edit prices or add dishes.');return}const d=Object.fromEntries(new FormData(e.target)),id=d.id||('dish-'+Date.now());const existing=menu.find(x=>x.id===id);const item={id,name:d.name.trim(),category:d.category,price:Number(d.price),desc:d.desc.trim(),emoji:existing?.emoji||'🍽️',image:existing?.image||'',tag:existing?.tag||'Made fresh',rating:existing?.rating||'4.8',available:existing?.available!==false};const idx=menu.findIndex(x=>x.id===id);if(idx>=0)menu[idx]=item;else menu.push(item);save(STORAGE.menu,menu);renderAdminDashboard('Menu');renderMenu();showToast(idx>=0?'Menu item updated.':'Menu item added.') }});
$('#adminContent').addEventListener('click',e=>{const tab=e.target.closest('[data-admin-tab]');if(tab){renderAdminDashboard(tab.dataset.adminTab);return}if(e.target.closest('#adminLogout')){adminRole='';lastStaffNotice=null;sessionStorage.removeItem(STORAGE.admin);renderAdminLogin();return}if(e.target.closest('#adminVisitSite')){closePanels();return}const vr=e.target.closest('[data-view-receipt]');if(vr){openReceiptLightbox(vr.dataset.viewReceipt);return}const ap=e.target.closest('[data-approve-order]');if(ap){const o=orders.find(x=>x.id===ap.dataset.approveOrder);if(o){o.paymentStatus='Verified';o.status='Preparing';save(STORAGE.orders,orders);lastStaffNotice={text:`Payment verified for ${o.id} — food prep started!`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'approved'))};renderAdminDashboard('Orders');showToast(`Payment verified & ${o.id} moved to Preparing.`)}return}if(e.target.closest('#addMenuOpen')){menuForm();return}if(e.target.closest('#cancelDishEdit')){$('#menuEditor').innerHTML='';return}const edit=e.target.closest('[data-edit-dish]');if(edit){if(!isOwner()){showToast('Only Admin / Owner can edit menu items.');return}menuForm(menu.find(d=>d.id===edit.dataset.editDish));return}const toggle=e.target.closest('[data-toggle-dish]');if(toggle){if(!isOwner()){showToast('Only Admin / Owner can change menu availability.');return}const d=menu.find(x=>x.id===toggle.dataset.toggleDish);d.available=d.available===false;save(STORAGE.menu,menu);renderAdminDashboard('Menu');renderMenu();showToast(d.available?'Item is back on the menu.':'Item paused.');return}const del=e.target.closest('[data-delete-dish]');if(del){if(!isOwner()){showToast('Only Admin / Owner can delete menu items.');return}const d=menu.find(x=>x.id===del.dataset.deleteDish);if(confirm(`Delete ${d.name} from the menu?`)){menu=menu.filter(x=>x.id!==d.id);delete cart[d.id];save(STORAGE.menu,menu);save(STORAGE.cart,cart);renderAdminDashboard('Menu');renderMenu();drawCart()}}});
$('#adminContent').addEventListener('change',e=>{const os=e.target.closest('[data-order-status]');if(os){const o=orders.find(x=>x.id===os.dataset.orderStatus);if(o){o.status=os.value;save(STORAGE.orders,orders);if(o.status==='Ready'){lastStaffNotice={text:`Order ${o.id} is ready! Send WhatsApp update to ${o.name}.`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'ready'))}}else if(o.status==='Preparing'){lastStaffNotice={text:`Order ${o.id} is now being prepared.`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'approved'))}}renderAdminDashboard('Orders');showToast(`Order ${o.id} marked ${o.status.toLowerCase()}.`)}return}const ps=e.target.closest('[data-payment-status]');if(ps){const o=orders.find(x=>x.id===ps.dataset.paymentStatus);if(o){o.paymentStatus=ps.value;if(ps.value==='Verified'&&o.status==='Awaiting Payment')o.status='Preparing';save(STORAGE.orders,orders);if(ps.value==='Verified'){lastStaffNotice={text:`Payment verified for ${o.id}. Notify ${o.name} on WhatsApp.`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'approved'))}}else if(ps.value==='Rejected'){lastStaffNotice={text:`Payment rejected for ${o.id}. Notify ${o.name} on WhatsApp.`,url:customerWhatsAppLink(o.phone,staffCustomerMessage(o,'rejected'))}}renderAdminDashboard('Orders');showToast(`Payment for ${o.id} marked ${ps.value.toLowerCase()}.`)}return}const rs=e.target.closest('[data-reservation-status]');if(rs){const r=reservations.find(x=>x.id===rs.dataset.reservationStatus);if(r){r.status=rs.value;save(STORAGE.reservations,reservations);renderAdminDashboard('Reservations');showToast('Reservation status updated.')}}});
