// Scroll-triggered reveals and header elevation
(function initMotion(){
  const header=$('.site-header');
  if(header){const onScroll=()=>header.classList.toggle('scrolled',window.scrollY>24);onScroll();window.addEventListener('scroll',onScroll,{passive:true})}
  const targets=$$('.quick-info > div, .section-heading, .story-image, .story-copy, .perks .eyebrow, .perks h2, .perk-grid article, .visit-copy, .map-card, .reserve-card');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){targets.forEach(el=>el.classList.add('is-visible'));return}
  targets.forEach((el,i)=>{el.classList.add('reveal');const parent=el.parentElement;if(parent&&(parent.classList.contains('perk-grid')||parent.classList.contains('quick-info'))){const idx=[...parent.children].indexOf(el);el.style.setProperty('--reveal-delay',`${idx*90}ms`)}});
  const io=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}})},{threshold:0.12,rootMargin:'0px 0px -40px 0px'});
  targets.forEach(el=>io.observe(el));
})();
